mapper.select:
SELECT SQL_CALC_FOUND_ROWS pa.alarm_id, pa.menu_type, pa.menu_type_id, pa.sender_mb_id, pa.receiver_mb_id, gm.mb_nick, sgm.mb_nick AS sender_mb_nick, pa.read_yn, pa.send_ymd, pa.contents, pdi.device_type FROM pet_alarm pa LEFT JOIN g5_member gm ON pa.receiver_mb_id = gm.mb_id LEFT JOIN pet_device_info pdi ON pa.receiver_mb_id = pdi.mb_id LEFT JOIN g5_member sgm ON pa.sender_mb_id = sgm.mb_id WHERE pa.del_fl = 0 AND pa.receiver_mb_id = #{mbId}
AND pa.menu_type = #{menuType}
ORDER BY pa.create_ymd DESC LIMIT #{pageNo}, #{pageSize};

mapper.update:
UPDATE pet_alarm
SET
    read_yn = 1
WHERE del_fl = 0

    AND alarm_id = #{alarmId}

AND receiver_mb_id = #{mbId};
